RTC_THREAD_LAYOUT_VERSION="v4.1"

# Tier id for a physical core count. Mirrors
# SelectThreadConfigsForCoreCount() in thread_config_generated.hpp.
_rtc_layout_tier() {
  local ncpu="$1"
  if [[ "$ncpu" -ge 16 ]]; then
    echo 16
  elif [[ "$ncpu" -ge 14 ]]; then
    echo 14
  elif [[ "$ncpu" -ge 12 ]]; then
    echo 12
  elif [[ "$ncpu" -ge 10 ]]; then
    echo 10
  elif [[ "$ncpu" -ge 8 ]]; then
    echo 8
  elif [[ "$ncpu" -ge 6 ]]; then
    echo 6
  else
    echo 4
  fi
}

# get_role_spec <role> [ncpu] -> "<slot> <policy> <priority> <nice>"
