get_role_slot() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f1
}

get_role_policy() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f2
}

get_role_priority() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f3
}

get_role_nice() {
  local spec
  spec=$(get_role_spec "$@") || return 1
  echo "$spec" | cut -d" " -f4
}

# MPC slots (main first, then workers) as CSV. $1 overrides the detected
# physical core count so print_thread_layout and the tests can render a
# tier this machine does not have.
get_mpc_cores() {
  local ncpu="${1:-$(get_physical_cores)}"
  local tier
  tier=$(_rtc_layout_tier "$ncpu")
  case "$tier" in
    4) echo "3" ;;
    6) echo "3" ;;
    8) echo "3" ;;
    10) echo "3,4" ;;
    12) echo "3,4,5" ;;
    14) echo "3,4,5" ;;
    16) echo "3,4,5" ;;
  esac
}

# RT group slots: rt_control + rt_callback + MPC (main + workers).
# Base for get_rt_cores_with_siblings() / get_cm_shield_cpus().
get_rt_cores() {
  local ncpu="${1:-$(get_physical_cores)}"
  local tier
  tier=$(_rtc_layout_tier "$ncpu")
  case "$tier" in
    4) echo "1,2,3" ;;
    6) echo "1,2,3" ;;
    8) echo "1,2,3" ;;
    10) echo "1,2,3,4" ;;
    12) echo "1,2,3,4,5" ;;
    14) echo "1,2,3,4,5" ;;
    16) echo "1,2,3,4,5" ;;
  esac
}

# nrt_logging + nrt_callback slots, deduplicated and ascending. On the
# degraded tier both share the OS slot -- callers that shield must drop
# the OS slot (get_cm_shield_cpus does), never widen onto it.
get_nrt_cores() {
  local ncpu="${1:-$(get_physical_cores)}"
  local tier
  tier=$(_rtc_layout_tier "$ncpu")
  case "$tier" in
    4) echo "0" ;;
    6) echo "5" ;;
    8) echo "6,7" ;;
    10) echo "7,8" ;;
    12) echo "8,9" ;;
    14) echo "8,9" ;;
    16) echo "8,9" ;;
  esac
}

# Slot the external arm driver process belongs on (launch taskset target).
get_arm_driver_slot() {
  local ncpu="${1:-$(get_physical_cores)}"
  local tier
  tier=$(_rtc_layout_tier "$ncpu")
  case "$tier" in
    4) echo "0" ;;
    6) echo "4" ;;
    8) echo "4" ;;
    10) echo "5" ;;
    12) echo "6" ;;
    14) echo "6" ;;
    16) echo "6" ;;
